B.agO=new A.c0("\u0905\u092a\u0928\u0940 \u092d\u093e\u0937\u093e, \u0905\u092a\u0928\u093e \u0936\u0939\u0930 \u0914\u0930 \u0910\u092a \u0915\u0947 \u091c\u094b \u0939\u093f\u0938\u094d\u0938\u0947 \u091a\u093e\u0939\u093f\u090f \u0935\u094b \u091a\u0941\u0928\u093f\u090f\u0964 \u0939\u094b\u092e \u092a\u0930 \u0938\u093f\u0930\u094d\u092b\u093c \u0935\u0939\u0940 \u0926\u093f\u0916\u0947\u0917\u093e\u0964 \u092c\u093e\u0926 \u092e\u0947\u0902 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u2192 \u092e\u0949\u0921\u094d\u092f\u0942\u0932 \u092e\u0947\u0902 \u0915\u092d\u0940 \u092d\u0940 \u092c\u0926\u0932 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u0910\u092a \u0907\u0902\u091f\u0930\u0928\u0947\u091f \u0915\u0947 \u092c\u093f\u0928\u093e \u092d\u0940 \u091a\u0932\u0924\u093e \u0939\u0948\u0964","\u0936\u0941\u0930\u0941\u0906\u0924")
B.ah1=new A.c0('\u0915\u093c\u0941\u0930\u0906\u0928 \u0916\u094b\u0932\u093f\u090f \u2192 \u0938\u0942\u0930\u0924 \u092f\u093e \u092a\u093e\u0930\u093e \u091a\u0941\u0928\u093f\u090f\u0964 \u092a\u0922\u093c\u0928\u0947 \u0915\u0940 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 (\u0938\u094d\u0932\u093e\u0907\u0921\u0930 \u0935\u093e\u0932\u093e \u0906\u0907\u0915\u0928) \u092e\u0947\u0902 \u0907\u0902\u0921\u094b\u092a\u093e\u0915 \u092f\u093e \u0909\u0938\u094d\u092e\u093e\u0928\u0940 \u0932\u093f\u092a\u093f \u091a\u0941\u0928\u093f\u090f \u0914\u0930 \u0905\u0915\u094d\u0937\u0930 \u092c\u0921\u093c\u0947 \u0915\u0940\u091c\u093f\u090f\u0964 \u0939\u0930 \u0906\u092f\u0924 \u0915\u0947 \u0938\u093e\u0925 \u0909\u0938\u0915\u093e \u0939\u0935\u093e\u0932\u093e (\u091c\u0948\u0938\u0947 2:255) \u0926\u093f\u0916\u0924\u093e \u0939\u0948\u0964 \u0910\u092a \u092f\u093e\u0926 \u0930\u0916\u0924\u093e \u0939\u0948 \u0915\u093f \u0906\u092a \u0915\u0939\u093e\u0901 \u0930\u0941\u0915\u0947 \u0925\u0947 \u2014 \u0939\u094b\u092e \u092a\u0930 "\u091c\u0939\u093e\u0901 \u091b\u094b\u0921\u093c\u093e \u0925\u093e \u0935\u0939\u0940\u0902 \u0938\u0947 \u092a\u0922\u093c\u093f\u090f" \u0926\u092c\u093e\u0907\u090f\u0964',"\u0915\u093c\u0941\u0930\u0906\u0928 \u092a\u0922\u093c\u0928\u093e")
B.ahm=new A.c0("\u0906\u092f\u0924 \u0915\u0947 \u092a\u093e\u0938 \u092c\u0941\u0915\u092e\u093e\u0930\u094d\u0915 \u0906\u0907\u0915\u0928 \u0926\u092c\u093e\u0907\u090f, \u092f\u093e \u0906\u092f\u0924 \u0915\u094b \u0926\u0947\u0930 \u0924\u0915 \u0926\u092c\u093e\u0907\u090f: \u0939\u0935\u093e\u0932\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0915\u0949\u092a\u0940, \u092f\u093e \u0917\u093c\u0932\u0924\u0940 \u092c\u0924\u093e\u0907\u090f\u0964 \u0916\u094b\u091c \u092e\u0947\u0902 \u0905\u0930\u092c\u0940, \u0909\u0930\u094d\u0926\u0942, \u0938\u0942\u0930\u0924 \u0915\u093e \u0928\u093e\u092e \u0915\u093f\u0938\u0940 \u092d\u0940 \u0938\u094d\u092a\u0947\u0932\u093f\u0902\u0917 \u092e\u0947\u0902 (yasin, yaseen) \u092f\u093e \u0939\u0935\u093e\u0932\u093e \u091c\u0948\u0938\u0947 36:1 \u0932\u093f\u0916\u093f\u090f\u0964","\u092c\u0941\u0915\u092e\u093e\u0930\u094d\u0915, \u0915\u0949\u092a\u0940 \u0914\u0930 \u0916\u094b\u091c")
B.ahf=new A.c0("\u0924\u0930\u094d\u091c\u0941\u092e\u093e \u0924\u092d\u0940 \u0926\u093f\u0916\u0947\u0917\u093e \u091c\u092c \u0939\u092e\u093e\u0930\u0947 \u0909\u0932\u092e\u093e \u0909\u0938\u0915\u0947 \u0938\u094d\u0930\u094b\u0924 \u0915\u0940 \u0924\u0938\u094d\u0926\u0940\u0915\u093c \u0915\u0930 \u0926\u0947\u0902\u0917\u0947\u0964 \u0924\u092c \u0924\u0915 \u092a\u0922\u093c\u0928\u0947 \u0935\u093e\u0932\u0947 \u092a\u0947\u091c \u092a\u0930 \u090f\u0915 \u0928\u094b\u091f \u0926\u093f\u0916\u0924\u093e \u0939\u0948\u0964","\u0924\u0930\u094d\u091c\u0941\u092e\u093e")
B.aht=new A.c0('\u0905\u092a\u0928\u093e \u0936\u0939\u0930 \u091a\u0941\u0928\u093f\u090f \u092f\u093e "\u092e\u0947\u0930\u0940 \u0905\u092d\u0940 \u0915\u0940 \u091c\u0917\u0939 \u0932\u0940\u091c\u093f\u090f" \u0926\u092c\u093e\u0907\u090f\u0964 \u0939\u093f\u0938\u093e\u092c \u092f\u0942\u0928\u093f\u0935\u0930\u094d\u0938\u093f\u091f\u0940 \u0911\u092b\u093c \u0907\u0938\u094d\u0932\u093e\u092e\u093f\u0915 \u0938\u093e\u0907\u0902\u0938\u0947\u091c\u093c, \u0915\u0930\u093e\u091a\u0940 \u0914\u0930 \u0939\u0928\u092b\u093c\u0940 \u0905\u0938\u094d\u0930 \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0939\u0948\u0964 \u090f\u0921\u0935\u093e\u0902\u0938 \u092e\u094b\u0921 (\u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u092e\u0947\u0902 \u0906\u0938\u093e\u0928 \u092e\u094b\u0921 \u092c\u0902\u0926 \u0915\u0930\u0915\u0947) \u092e\u0947\u0902 \u0939\u0930 \u0935\u0915\u093c\u094d\u0924 \u0915\u094b \u0915\u0941\u091b \u092e\u093f\u0928\u091f \u0906\u0917\u0947-\u092a\u0940\u091b\u0947 \u0915\u0930\u0915\u0947 \u0905\u092a\u0928\u0940 \u092e\u0938\u094d\u091c\u093f\u0926 \u0938\u0947 \u092e\u093f\u0932\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u091a\u093e\u0901\u0926 \u0926\u093f\u0916\u0928\u0947 \u092e\u0947\u0902 \u092b\u093c\u0930\u094d\u0915\u093c \u0939\u094b \u0924\u094b \u0939\u093f\u091c\u0930\u0940 \u0924\u093e\u0930\u0940\u0916\u093c \xb12 \u0926\u093f\u0928 \u092c\u0926\u0932\u093f\u090f\u0964',"\u0928\u092e\u093e\u091c\u093c \u0915\u0947 \u0935\u0915\u093c\u094d\u0924")
B.ahc=new A.c0('\u092f\u093e\u0926-\u0926\u0939\u093e\u0928\u0940 \u0938\u093f\u0930\u094d\u092b\u093c \u0935\u093e\u0907\u092c\u094d\u0930\u0947\u091f \u0915\u0930\u0924\u0940 \u0939\u0948\u0964 \u090f\u0902\u0921\u094d\u0930\u0949\u092f\u0921 \u092a\u0930 "Alarms & reminders" \u0915\u0940 \u0907\u091c\u093e\u091c\u093c\u0924 \u0926\u0940\u091c\u093f\u090f \u0914\u0930 \u0907\u0938 \u0910\u092a \u0915\u093e \u092c\u0948\u091f\u0930\u0940 \u0911\u092a\u094d\u091f\u093f\u092e\u093e\u0907\u091c\u093c\u0947\u0936\u0928 \u092c\u0902\u0926 \u0915\u0940\u091c\u093f\u090f\u0964 Xiaomi, Redmi, Oppo, Vivo, Realme \u0914\u0930 \u0915\u0941\u091b Samsung \u092b\u093c\u094b\u0928 \u092e\u0947\u0902 "Autostart" \u091a\u093e\u0932\u0942 \u0915\u0940\u091c\u093f\u090f \u0914\u0930 \u092c\u0948\u091f\u0930\u0940 \u0915\u094b "No restrictions" \u092a\u0930 \u0930\u0916\u093f\u090f, \u0935\u0930\u0928\u093e \u092b\u093c\u094b\u0928 \u092f\u093e\u0926-\u0926\u0939\u093e\u0928\u0940 \u0930\u094b\u0915 \u0938\u0915\u0924\u093e \u0939\u0948\u0964',"\u092f\u093e\u0926-\u0926\u0939\u093e\u0928\u0940 \u0928\u0939\u0940\u0902 \u092c\u091c \u0930\u0939\u0940?")
B.agJ=new A.c0("\u092b\u093c\u094b\u0928 \u0915\u094b \u0938\u092e\u0924\u0932 \u0930\u0916\u093f\u090f \u0914\u0930 \u0932\u094b\u0939\u0947, \u091a\u0941\u0902\u092c\u0915 \u0914\u0930 \u092c\u093f\u091c\u0932\u0940 \u0915\u0947 \u0924\u093e\u0930\u094b\u0902 \u0938\u0947 \u0926\u0942\u0930 \u0930\u0916\u093f\u090f\u0964 \u0924\u0940\u0930 \u0917\u093c\u0932\u0924 \u0932\u0917\u0947 \u0924\u094b \u092b\u093c\u094b\u0928 \u0915\u094b 8 \u0915\u0947 \u0906\u0915\u093e\u0930 \u092e\u0947\u0902 \u0915\u0941\u091b \u092c\u093e\u0930 \u0918\u0941\u092e\u093e\u0907\u090f\u0964 \u0909\u0924\u094d\u0924\u0930 \u0938\u0947 \u0915\u094b\u0923 \u092d\u0940 \u0932\u093f\u0916\u093e \u0939\u094b\u0924\u093e \u0939\u0948, \u0915\u093f\u0938\u0940 \u092d\u0940 \u0915\u092e\u094d\u092a\u093e\u0938 \u0938\u0947 \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964","\u0915\u093c\u093f\u092c\u0932\u093e")
B.ahE=new A.c0("\u0924\u0938\u094d\u092c\u0940\u0939: \u0917\u093f\u0928\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0939\u0940\u0902 \u092d\u0940 \u091f\u0948\u092a \u0915\u0940\u091c\u093f\u090f; \u0932\u0915\u094d\u0937\u094d\u092f 33, 99, 100 \u092f\u093e 1000 \u091a\u0941\u0928\u093f\u090f\u0964 \u0928\u092e\u093e\u091c\u093c \u0930\u093f\u0915\u0949\u0930\u094d\u0921: \u0939\u0930 \u0928\u092e\u093e\u091c\u093c \u0915\u094b \u0935\u0915\u093c\u094d\u0924 \u092a\u0930, \u091c\u092e\u093e\u0905\u0924 \u0915\u0947 \u0938\u093e\u0925, \u0915\u093c\u091c\u093c\u093e \u092f\u093e \u091b\u0942\u091f \u0917\u0908 \u091a\u093f\u0939\u094d\u0928\u093f\u0924 \u0915\u0940\u091c\u093f\u090f\u0964 \u092f\u0939 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0938\u093f\u0930\u094d\u092b\u093c \u0906\u092a\u0915\u0947 \u092b\u093c\u094b\u0928 \u092e\u0947\u0902 \u0930\u0939\u0924\u093e \u0939\u0948, \u0915\u092d\u0940 \u0936\u0947\u092f\u0930 \u092f\u093e \u0924\u0941\u0932\u0928\u093e \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u093e\u0964","\u0924\u0938\u094d\u092c\u0940\u0939 \u0914\u0930 \u0928\u092e\u093e\u091c\u093c \u0930\u093f\u0915\u0949\u0930\u094d\u0921")
B.ahD=new A.c0("\u0915\u094b\u0908 \u0935\u093f\u091c\u094d\u091e\u093e\u092a\u0928 \u0928\u0939\u0940\u0902, \u0921\u0947\u091f\u093e \u092c\u0947\u091a\u0928\u093e \u0928\u0939\u0940\u0902\u0964 \u0906\u092a\u0915\u0940 \u091c\u0917\u0939 \u0938\u093f\u0930\u094d\u092b\u093c \u092b\u093c\u094b\u0928 \u092a\u0930 \u0935\u0915\u093c\u094d\u0924 \u0928\u093f\u0915\u093e\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0939\u094b\u0924\u0940 \u0939\u0948\u0964 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938, \u092c\u0941\u0915\u092e\u093e\u0930\u094d\u0915 \u0914\u0930 \u0928\u092e\u093e\u091c\u093c \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0907\u0938\u0940 \u092b\u093c\u094b\u0928 \u092e\u0947\u0902 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964","\u0928\u093f\u091c\u0924\u093e")
B.ahv=new A.c0("\u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u2192 \u0910\u092a \u0915\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 \u0914\u0930 \u0938\u094d\u0930\u094b\u0924 \u092e\u0947\u0902 \u0939\u0930 \u0907\u092c\u093e\u0930\u0924 \u0915\u093e \u0938\u094d\u0930\u094b\u0924, \u0909\u0938\u0915\u093e \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0914\u0930 \u0910\u092a \u0915\u093e \u0907\u0932\u094d\u092e\u0940 \u092e\u0947\u092f\u093e\u0930 \u0932\u093f\u0916\u093e \u0939\u0948\u0964 \u0915\u094b\u0908 \u0917\u093c\u0932\u0924\u0940 \u092e\u093f\u0932\u0947 \u0924\u094b \u0906\u092f\u0924 \u0915\u094b \u0926\u0947\u0930 \u0924\u0915 \u0926\u092c\u093e\u0907\u090f \u2192 \u0917\u093c\u0932\u0924\u0940 \u092c\u0924\u093e\u0907\u090f\u0964","\u0938\u094d\u0930\u094b\u0924 \u0914\u0930 \u0917\u093c\u0932\u0924\u093f\u092f\u093e\u0901")
