B.ah7=new A.c0("\u0627\u067e\u0646\u06cc \u0632\u0628\u0627\u0646\u060c \u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0627\u0648\u0631 \u0627\u06cc\u067e \u06a9\u06d2 \u0648\u06c1 \u062d\u0635\u06d2 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2 \u062c\u0648 \u0622\u067e \u06a9\u0648 \u0686\u0627\u06c1\u06cc\u06cc\u06ba\u06d4 \u06c1\u0648\u0645 \u067e\u0631 \u0635\u0631\u0641 \u0648\u06c1\u06cc \u062f\u06a9\u06be\u06d2 \u06af\u0627\u06d4 \u0628\u0639\u062f \u0645\u06cc\u06ba \u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u2190 \u0645\u0627\u0688\u06cc\u0648\u0644 \u0645\u06cc\u06ba \u06a9\u0628\u06be\u06cc \u0628\u06be\u06cc \u0628\u062f\u0644 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0627\u06cc\u067e \u0627\u0646\u0679\u0631\u0646\u06cc\u0679 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0628\u06be\u06cc \u0686\u0644\u062a\u06cc \u06c1\u06d2\u06d4","\u0622\u063a\u0627\u0632")
B.ahS=new A.c0('\u0642\u0631\u0622\u0646 \u06a9\u06be\u0648\u0644\u06cc\u06d2 \u2190 \u0633\u0648\u0631\u062a \u06cc\u0627 \u067e\u0627\u0631\u06c1 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2\u06d4 \u067e\u0691\u06be\u0646\u06d2 \u06a9\u06cc \u062a\u0631\u062a\u06cc\u0628\u0627\u062a (\u0633\u0644\u0627\u0626\u06cc\u0688\u0631 \u0648\u0627\u0644\u0627 \u0622\u0626\u06cc\u06a9\u0646) \u0645\u06cc\u06ba \u0627\u0646\u0688\u0648 \u067e\u0627\u06a9 \u06cc\u0627 \u0639\u062b\u0645\u0627\u0646\u06cc \u062e\u0637 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2 \u0627\u0648\u0631 \u062d\u0631\u0648\u0641 \u0628\u0691\u06d2 \u06a9\u06cc\u062c\u06cc\u06d2\u06d4 \u06c1\u0631 \u0622\u06cc\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0627\u0633 \u06a9\u0627 \u062d\u0648\u0627\u0644\u06c1 (\u062c\u06cc\u0633\u06d2 2:255) \u062f\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u06cc\u067e \u06cc\u0627\u062f \u0631\u06a9\u06be\u062a\u06cc \u06c1\u06d2 \u06a9\u06c1 \u0622\u067e \u06a9\u06c1\u0627\u06ba \u0631\u06a9\u06d2 \u062a\u06be\u06d2 \u2014 \u06c1\u0648\u0645 \u067e\u0631 "\u062c\u06c1\u0627\u06ba \u0686\u06be\u0648\u0691\u0627 \u062a\u06be\u0627 \u0648\u06c1\u06cc\u06ba \u0633\u06d2 \u067e\u0691\u06be\u06cc\u06d2" \u062f\u0628\u0627\u0626\u06cc\u06d2\u06d4',"\u0642\u0631\u0622\u0646 \u067e\u0691\u06be\u0646\u0627")
B.ahx=new A.c0("\u0622\u06cc\u062a \u06a9\u06d2 \u067e\u0627\u0633 \u0628\u064f\u06a9 \u0645\u0627\u0631\u06a9 \u06a9\u0627 \u0622\u0626\u06cc\u06a9\u0646 \u062f\u0628\u0627\u0626\u06cc\u06d2\u060c \u06cc\u0627 \u0622\u06cc\u062a \u06a9\u0648 \u062f\u06cc\u0631 \u062a\u06a9 \u062f\u0628\u0627\u0626\u06cc\u06d2: \u062d\u0648\u0627\u0644\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u0627\u067e\u06cc\u060c \u06cc\u0627 \u063a\u0644\u0637\u06cc \u06a9\u06cc \u0627\u0637\u0644\u0627\u0639\u06d4 \u062a\u0644\u0627\u0634 \u0645\u06cc\u06ba \u0639\u0631\u0628\u06cc\u060c \u0627\u0631\u062f\u0648\u060c \u0633\u0648\u0631\u062a \u06a9\u0627 \u0646\u0627\u0645 \u06a9\u0633\u06cc \u0628\u06be\u06cc \u06c1\u062c\u06d2 \u0645\u06cc\u06ba (yasin, yaseen) \u06cc\u0627 \u062d\u0648\u0627\u0644\u06c1 \u062c\u06cc\u0633\u06d2 36:1 \u0644\u06a9\u06be\u06cc\u06d2\u06d4","\u0628\u064f\u06a9 \u0645\u0627\u0631\u06a9\u060c \u06a9\u0627\u067e\u06cc \u0627\u0648\u0631 \u062a\u0644\u0627\u0634")
B.ahO=new A.c0("\u062a\u0631\u062c\u0645\u06c1 \u062a\u0628\u06be\u06cc \u062f\u06a9\u06be\u06d2 \u06af\u0627 \u062c\u0628 \u06c1\u0645\u0627\u0631\u06d2 \u0639\u0644\u0645\u0627\u0621 \u0627\u0633 \u06a9\u06d2 \u0645\u0627\u062e\u0630 \u06a9\u06cc \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631 \u062f\u06cc\u06ba \u06af\u06d2\u06d4 \u062a\u0628 \u062a\u06a9 \u067e\u0691\u06be\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0635\u0641\u062d\u06d2 \u067e\u0631 \u0627\u06cc\u06a9 \u0646\u0648\u0679 \u062f\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4","\u062a\u0631\u062c\u0645\u06c1")
B.ahG=new A.c0('\u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2 \u06cc\u0627 "\u0645\u06cc\u0631\u0627 \u0645\u0648\u062c\u0648\u062f\u06c1 \u0645\u0642\u0627\u0645 \u0644\u06cc\u062c\u06cc\u06d2" \u062f\u0628\u0627\u0626\u06cc\u06d2\u06d4 \u062d\u0633\u0627\u0628 \u06cc\u0648\u0646\u06cc\u0648\u0631\u0633\u0679\u06cc \u0622\u0641 \u0627\u0633\u0644\u0627\u0645\u06a9 \u0633\u0627\u0626\u0646\u0633\u0632\u060c \u06a9\u0631\u0627\u0686\u06cc \u0627\u0648\u0631 \u062d\u0646\u0641\u06cc \u0639\u0635\u0631 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u06c1\u06d2\u06d4 \u0627\u06cc\u0688\u0648\u0627\u0646\u0633 \u0645\u0648\u0688 (\u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u0645\u06cc\u06ba \u0622\u0633\u0627\u0646 \u0645\u0648\u0688 \u0628\u0646\u062f \u06a9\u0631 \u06a9\u06d2) \u0645\u06cc\u06ba \u06c1\u0631 \u0648\u0642\u062a \u06a9\u0648 \u0686\u0646\u062f \u0645\u0646\u0679 \u0622\u06af\u06d2 \u067e\u06cc\u0686\u06be\u06d2 \u06a9\u0631 \u06a9\u06d2 \u0627\u067e\u0646\u06cc \u0645\u0633\u062c\u062f \u0633\u06d2 \u0645\u0644\u0627 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0631\u0624\u06cc\u062a\u0650 \u06c1\u0644\u0627\u0644 \u0645\u06cc\u06ba \u0641\u0631\u0642 \u06c1\u0648 \u062a\u0648 \u06c1\u062c\u0631\u06cc \u062a\u0627\u0631\u06cc\u062e \xb12 \u062f\u0646 \u0628\u062f\u0644\u06cc\u06d2\u06d4',"\u0627\u0648\u0642\u0627\u062a\u0650 \u0646\u0645\u0627\u0632")
B.ah_=new A.c0('\u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc \u0635\u0631\u0641 \u0648\u0627\u0626\u0628\u0631\u06cc\u0679 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u06d4 \u0627\u06cc\u0646\u0688\u0631\u0627\u0626\u06cc\u0688 \u067e\u0631 "Alarms & reminders" \u06a9\u06cc \u0627\u062c\u0627\u0632\u062a \u062f\u06cc\u062c\u06cc\u06d2 \u0627\u0648\u0631 \u0627\u0633 \u0627\u06cc\u067e \u06a9\u06cc \u0628\u06cc\u0679\u0631\u06cc \u0622\u067e\u0679\u06cc\u0645\u0627\u0626\u0632\u06cc\u0634\u0646 \u0628\u0646\u062f \u06a9\u06cc\u062c\u06cc\u06d2\u06d4 Xiaomi\u060c Redmi\u060c Oppo\u060c Vivo\u060c Realme \u0627\u0648\u0631 \u0628\u0639\u0636 Samsung \u0641\u0648\u0646\u0632 \u0645\u06cc\u06ba "Autostart" \u0622\u0646 \u06a9\u06cc\u062c\u06cc\u06d2 \u0627\u0648\u0631 \u0628\u06cc\u0679\u0631\u06cc \u06a9\u0648 "No restrictions" \u067e\u0631 \u0631\u06a9\u06be\u06cc\u06d2\u060c \u0648\u0631\u0646\u06c1 \u0641\u0648\u0646 \u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc \u0631\u0648\u06a9 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4',"\u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc \u0646\u06c1\u06cc\u06ba \u0628\u062c \u0631\u06c1\u06cc\u061f")
B.ahi=new A.c0("\u0641\u0648\u0646 \u06a9\u0648 \u0633\u06cc\u062f\u06be\u0627 \u0631\u06a9\u06be\u06cc\u06d2 \u0627\u0648\u0631 \u0644\u0648\u06c1\u06d2\u060c \u0645\u0642\u0646\u0627\u0637\u06cc\u0633 \u0627\u0648\u0631 \u0628\u062c\u0644\u06cc \u06a9\u06d2 \u062a\u0627\u0631\u0648\u06ba \u0633\u06d2 \u062f\u0648\u0631 \u0631\u06a9\u06be\u06cc\u06d2\u06d4 \u062a\u06cc\u0631 \u063a\u0644\u0637 \u0644\u06af\u06d2 \u062a\u0648 \u0641\u0648\u0646 \u06a9\u0648 \u06f8 \u06a9\u06cc \u0634\u06a9\u0644 \u0645\u06cc\u06ba \u0686\u0646\u062f \u0628\u0627\u0631 \u06af\u06be\u0645\u0627\u0626\u06cc\u06d2\u06d4 \u0634\u0645\u0627\u0644 \u0633\u06d2 \u0632\u0627\u0648\u06cc\u06c1 \u0628\u06be\u06cc \u0644\u06a9\u06be\u0627 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u06a9\u0633\u06cc \u0628\u06be\u06cc \u06a9\u0645\u067e\u0627\u0633 \u0633\u06d2 \u062f\u06cc\u06a9\u06be \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u0642\u0628\u0644\u06c1")
B.ahB=new A.c0("\u062a\u0633\u0628\u06cc\u062d: \u06af\u0646\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u06c1\u06cc\u06ba \u0628\u06be\u06cc \u0679\u06cc\u067e \u06a9\u06cc\u062c\u06cc\u06d2\u061b \u06c1\u062f\u0641 33\u060c 99\u060c 100 \u06cc\u0627 1000 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2\u06d4 \u0646\u0645\u0627\u0632 \u06a9\u0627 \u0631\u06cc\u06a9\u0627\u0631\u0688: \u06c1\u0631 \u0646\u0645\u0627\u0632 \u06a9\u0648 \u0648\u0642\u062a \u067e\u0631\u060c \u062c\u0645\u0627\u0639\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be\u060c \u0642\u0636\u0627 \u06cc\u0627 \u0686\u06be\u0648\u0679 \u06af\u0626\u06cc \u06a9\u0627 \u0646\u0634\u0627\u0646 \u0644\u06af\u0627\u0626\u06cc\u06d2\u06d4 \u06cc\u06c1 \u0631\u06cc\u06a9\u0627\u0631\u0688 \u0635\u0631\u0641 \u0622\u067e \u06a9\u06d2 \u0641\u0648\u0646 \u0645\u06cc\u06ba \u0631\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u06a9\u0628\u06be\u06cc \u0634\u06cc\u0626\u0631 \u06cc\u0627 \u0645\u0648\u0627\u0632\u0646\u06c1 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627\u06d4","\u062a\u0633\u0628\u06cc\u062d \u0627\u0648\u0631 \u0646\u0645\u0627\u0632 \u06a9\u0627 \u0631\u06cc\u06a9\u0627\u0631\u0688")
B.ahJ=new A.c0("\u06a9\u0648\u0626\u06cc \u0627\u0634\u062a\u06c1\u0627\u0631 \u0646\u06c1\u06cc\u06ba\u060c \u0688\u06cc\u0679\u0627 \u06a9\u06cc \u0641\u0631\u0648\u062e\u062a \u0646\u06c1\u06cc\u06ba\u06d4 \u0622\u067e \u06a9\u0627 \u0645\u0642\u0627\u0645 \u0635\u0631\u0641 \u0641\u0648\u0646 \u067e\u0631 \u0627\u0648\u0642\u0627\u062a \u0646\u06a9\u0627\u0644\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4 \u062a\u0631\u062a\u06cc\u0628\u0627\u062a\u060c \u0628\u064f\u06a9 \u0645\u0627\u0631\u06a9 \u0627\u0648\u0631 \u0646\u0645\u0627\u0632 \u06a9\u0627 \u0631\u06cc\u06a9\u0627\u0631\u0688 \u0627\u0633\u06cc \u0641\u0648\u0646 \u0645\u06cc\u06ba \u0631\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u0631\u0627\u0632\u062f\u0627\u0631\u06cc")
B.agV=new A.c0("\u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u2190 \u062a\u0639\u0627\u0631\u0641 \u0627\u0648\u0631 \u0645\u0627\u062e\u0630 \u0645\u06cc\u06ba \u06c1\u0631 \u0639\u0628\u0627\u0631\u062a \u06a9\u0627 \u0645\u0627\u062e\u0630\u060c \u0627\u0633 \u06a9\u0627 \u0644\u0627\u0626\u0633\u0646\u0633 \u0627\u0648\u0631 \u0627\u06cc\u067e \u06a9\u0627 \u0639\u0644\u0645\u06cc \u0645\u0639\u06cc\u0627\u0631 \u0644\u06a9\u06be\u0627 \u06c1\u06d2\u06d4 \u06a9\u0648\u0626\u06cc \u063a\u0644\u0637\u06cc \u0645\u0644\u06d2 \u062a\u0648 \u0622\u06cc\u062a \u06a9\u0648 \u062f\u06cc\u0631 \u062a\u06a9 \u062f\u0628\u0627\u0626\u06cc\u06d2 \u2190 \u063a\u0644\u0637\u06cc \u06a9\u06cc \u0627\u0637\u0644\u0627\u0639 \u062f\u06cc\u062c\u06cc\u06d2\u06d4","\u0645\u0627\u062e\u0630 \u0627\u0648\u0631 \u063a\u0644\u0637\u06cc\u0627\u06ba")
